import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Goal-mode rework plan","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/strategies/goal-mode-rework-plan.html"}],["meta",{"property":"og:title","content":"Goal-mode rework plan | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/strategies/goal-mode-rework-plan.html"}],["meta",{"name":"twitter:title","content":"Goal-mode rework plan | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"strategies/goal-mode-rework-plan.md","filePath":"strategies/goal-mode-rework-plan.md","lastUpdated":1793947944000}`),a={name:`strategies/goal-mode-rework-plan.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="goal-mode-rework-plan" tabindex="-1">Goal-mode rework plan <a class="header-anchor" href="#goal-mode-rework-plan" aria-label="Permalink to “Goal-mode rework plan”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p><strong>Status: Under development — not user selectable.</strong></p><p>Goal mode is disabled in the browser and rejected by the public configuration validator and JSON schema. This is intentional. Do not re-enable it until every acceptance gate below is complete.</p><h2 id="architecture-decision" tabindex="-1">Architecture decision <a class="header-anchor" href="#architecture-decision" aria-label="Permalink to “Architecture decision”">​</a></h2><p>The current four strategies were built around a finite scoped date range. Preserve that design rather than forcing every strategy to optimise a second objective.</p><table tabindex="0"><thead><tr><th>Component</th><th>Scoped date-range mode</th><th>Future Goal mode</th></tr></thead><tbody><tr><td>Simulation runtime</td><td>Authoritative financial execution and validation</td><td>Same strategy-independent accounting and validation</td></tr><tr><td>Greedy</td><td>Existing scoped heuristic, unchanged</td><td>Not planned</td></tr><tr><td>GSS</td><td>Existing scoped recursive planner, unchanged</td><td>Not planned</td></tr><tr><td>Absolute R+</td><td>Existing scoped bounded search, unchanged</td><td>Not planned</td></tr><tr><td>Absolute R</td><td>Existing scoped exhaustive search</td><td>First and only planned Goal optimiser</td></tr></tbody></table><p>The runtime determines whether a decision sequence is financially valid. The strategy determines which valid sequence is best. Goal-vs-Scoped objective selection belongs at the strategy/search boundary, not in the authoritative simulation engine.</p><p>The internal goal runtime and provenance code may remain available to direct unit tests while the public mode is disabled. Internal tests do not make Goal mode a supported product feature.</p><h2 id="goal-objective" tabindex="-1">Goal objective <a class="header-anchor" href="#goal-objective" aria-label="Permalink to “Goal objective”">​</a></h2><p>The future Goal objective is the earliest event boundary at which the configured cumulative net interest is actually credited to the consolidation account. The target must be achieved using authoritative runtime accounting after AIT and the applicable transfer-fee allocation. Principal, projected interest and uncredited interest are not achievement.</p><p>The user should supply a start date and target, not an arbitrary end date. Any internal safety horizon is only a guard against unbounded execution and must not become a terminal-value optimisation horizon.</p><h2 id="non-negotiable-constraints" tabindex="-1">Non-negotiable constraints <a class="header-anchor" href="#non-negotiable-constraints" aria-label="Permalink to “Non-negotiable constraints”">​</a></h2><ol><li>Preserve scoped results, decision paths, diagnostics and practical performance for Greedy, GSS, Absolute R and Absolute R+.</li><li>Do not add Goal-specific policy branches to Greedy, GSS or Absolute R+.</li><li>Keep the simulation runtime strategy-independent. It owns actual balances, cash flows, maturity events, outflow settlement, provenance and finalisation.</li><li>Keep Goal objective ranking and search pruning inside Absolute R&#39;s strategy implementation.</li><li>Never weaken strict outflow, liquidity or provenance debit validation to make a Goal candidate appear feasible.</li><li>Replay selected Goal candidates through the authoritative runtime. Search projections are estimates, not accounting authority.</li><li>Report an optimality proof only if Absolute R exhausts the relevant decision space and every pruning rule is admissible for earliest achievement.</li><li>Do not expose the Goal selector, schema contract or CLI mode until the full release gate passes.</li></ol><h2 id="execution-phases" tabindex="-1">Execution phases <a class="header-anchor" href="#execution-phases" aria-label="Permalink to “Execution phases”">​</a></h2><h3 id="phase-0-—-re-establish-the-current-baseline" tabindex="-1">Phase 0 — Re-establish the current baseline <a class="header-anchor" href="#phase-0-—-re-establish-the-current-baseline" aria-label="Permalink to “Phase 0 — Re-establish the current baseline”">​</a></h3><ul><li>Inspect the merged goal-aware implementation and identify code paths that currently branch on Goal mode.</li><li>Record current Scoped parity fixtures and diagnostics for all four strategies.</li><li>Identify the exact provenance debit failure path reported in the browser, including no-outflow scenarios and Absolute+.</li><li>Separate verified causes from hypotheses; do not widen debit tolerances without proving the accounting reconciliation rule.</li></ul><p><strong>Acceptance:</strong> source map, reproducible failing test for any confirmed accounting defect, and a recorded scoped baseline.</p><h3 id="phase-1-—-isolate-objective-ownership" tabindex="-1">Phase 1 — Isolate objective ownership <a class="header-anchor" href="#phase-1-—-isolate-objective-ownership" aria-label="Permalink to “Phase 1 — Isolate objective ownership”">​</a></h3><ul><li>Keep runtime event processing and financial validation common.</li><li>Move any objective-specific stopping, candidate ordering, ranking, state equivalence and pruning decisions to Absolute R&#39;s search boundary.</li><li>Ensure the public configuration contract remains scoped-only.</li><li>Remove Goal-specific search work from Greedy, GSS and Absolute R+ only where it is safe and covered by scoped parity tests. Do not make broad refactors merely for symmetry.</li></ul><p><strong>Acceptance:</strong> all four strategies remain scoped-only in public execution; scoped parity tests remain exact.</p><h3 id="phase-2-—-implement-goal-search-in-absolute-r-only" tabindex="-1">Phase 2 — Implement Goal search in Absolute R only <a class="header-anchor" href="#phase-2-—-implement-goal-search-in-absolute-r-only" aria-label="Permalink to “Phase 2 — Implement Goal search in Absolute R only”">​</a></h3><ul><li>Define earliest authoritative consolidation-credit date as the primary objective.</li><li>Define deterministic same-date tie-breaks and unachieved-candidate ordering.</li><li>Preserve all candidate paths that may achieve earlier, even if they have lower terminal interest.</li><li>Use only proven-safe Goal pruning; disable scoped terminal-value bounds or memo rules that are not admissible for earliest achievement.</li><li>Do not let the internal safety horizon act as a user scope or terminal-value objective.</li></ul><p><strong>Acceptance:</strong> small adversarial Goal cases match a deterministic exhaustive oracle; Absolute R&#39;s proof flag is honest.</p><h3 id="phase-3-—-harden-financial-accounting-and-provenance" tabindex="-1">Phase 3 — Harden financial accounting and provenance <a class="header-anchor" href="#phase-3-—-harden-financial-accounting-and-provenance" aria-label="Permalink to “Phase 3 — Harden financial accounting and provenance”">​</a></h3><ul><li>Reconcile scalar balances and provenance components at every relevant transition.</li><li>Audit pending cash-flow aggregation, rounding, same-day maturities, periodic payouts, transfers, consolidation and reinvestment.</li><li>Improve debit failure diagnostics with account, requested amount, available provenance, scalar balance, discrepancy and operation context.</li><li>Keep real overdraws and strict outflow failures rejected.</li></ul><p><strong>Acceptance:</strong> no false provenance debit failures in supported no-outflow cases; genuine overdraw and invalid transfer tests still fail.</p><h3 id="phase-4-—-adversarial-and-sensitivity-verification" tabindex="-1">Phase 4 — Adversarial and sensitivity verification <a class="header-anchor" href="#phase-4-—-adversarial-and-sensitivity-verification" aria-label="Permalink to “Phase 4 — Adversarial and sensitivity verification”">​</a></h3><p>Cover at minimum:</p><ul><li>Multiple same-day FD maturities and periodic interest payouts.</li><li>Mixed principal, uncredited interest and counted interest.</li><li>AIT and transfer-fee allocation.</li><li>Repeated transfer, consolidation and reinvestment cycles.</li><li>Future inflows and strict outflows.</li><li>Different accounts, banks and eFD eligibility.</li><li>Faster low-interest paths versus slower high-interest paths.</li><li>Targets just below, at and above a credited payout.</li><li>Unreachable targets and safety-horizon exhaustion.</li></ul><p>Measure actual achievement date, credited interest, fees, operations, expanded/pruned states, runtime and proof status. Keep the existing Scoped sensitivity matrix separate.</p><p><strong>Acceptance:</strong> all adversarial tests pass; Scoped benchmarks show no regression; Goal results match the exhaustive oracle for tractable cases.</p><h3 id="phase-5-—-re-enable-goal-mode-only-after-review" tabindex="-1">Phase 5 — Re-enable Goal mode only after review <a class="header-anchor" href="#phase-5-—-re-enable-goal-mode-only-after-review" aria-label="Permalink to “Phase 5 — Re-enable Goal mode only after review”">​</a></h3><p>Only after Phases 0–4 pass:</p><ul><li>Re-enable the Goal mode selector.</li><li>Restore Goal mode to the public schema and semantic validator.</li><li>Expose Absolute R as the only selectable Goal strategy.</li><li>Keep Greedy, GSS and Absolute R+ unavailable in Goal mode.</li><li>Update browser, CLI, reports, documentation, sensitivity graphs and CI.</li><li>Run full tests, docs build, CodeQL and final diff review.</li></ul><p><strong>Acceptance:</strong> public UI, CLI, schema and docs agree; all CI gates pass; no Goal feature is exposed prematurely.</p><h2 id="current-implementation-boundary" tabindex="-1">Current implementation boundary <a class="header-anchor" href="#current-implementation-boundary" aria-label="Permalink to “Current implementation boundary”">​</a></h2><p>The current public product remains scoped date-range only. The existing internal Goal code is retained for investigation, but is not accepted as complete. In particular, the reported error <code>Provenance debit exceeds the available balance</code> remains a separate accounting investigation until reproduced and fixed with focused tests.</p>`,38)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};